# Set a grade's rate. Validate first so a bad grade or percent is a 400, not a 404.
# A viewer may change nothing: refused before anything is read or written.
viewer:
  class: net.officefloor.hq.app.role.CheckCanChange
  next: validate
validate:
  class: net.officefloor.hq.app.rate.ValidateRate
  next: load
load:
  class: net.officefloor.hq.app.sheet.LoadSheet
  govern: [ transaction ]
  next: before
# The sheet's figures before the change, so the rollup lines tell which moved.
before:
  class: net.officefloor.hq.app.rollup.TakeRollup
  govern: [ transaction ]
  next: save
save:
  class: net.officefloor.hq.app.rate.SaveRate
  govern: [ transaction ]
  next: audit
# Last before the response: every rule has passed and the change is saved.
audit:
  class: net.officefloor.hq.app.rate.AuditRateSet
  govern: [ transaction ]
  next: rollup
# After the change's own lines: the figures it moved.
rollup:
  class: net.officefloor.hq.app.rollup.AuditRollup
  govern: [ transaction ]
  next: respond
respond:
  class: net.officefloor.hq.app.rate.RespondWithRate
  govern: [ transaction ]
# The rates set on a sheet, by grade.
load:
  class: net.officefloor.hq.app.sheet.LoadSheet
  govern: [ readonly-transaction ]
  next: respond
respond:
  class: net.officefloor.hq.app.rate.RespondWithRates
  govern: [ readonly-transaction ]
package net.officefloor.hq.app.rate;

import java.math.BigDecimal;
import java.time.LocalDate;
import java.util.Comparator;
import java.util.List;
import java.util.Objects;
import java.util.Optional;

/**
 * A grade's rate on a sheet: a percent with two decimals, from a date (null: from the beginning of
 * time) through a date (null: with no end). Its level is how far up the sheet's parent chain it is
 * set: 0 on the sheet itself, 1 on its parent, up to {@link #MAX_LEVEL}, then on past them
 * the sheet it was cloned from and its own. Its version counts how many
 * times a rate has been set for its grade and from-date (1 for the first); it is the newest of them.
 * A forward-only rate (saved with a from-date on or after the sheet's today) applies only to claims
 * added after it was saved: those with an id above {@code addedAfter} (null: it applies to every
 * claim); an older claim sees the version it {@code replaced} (null: none) instead.
 */
public record Rate(String sheetId, String grade, BigDecimal pct, LocalDate from, LocalDate to, int level,
        int version, Long addedAfter, Rate replaced) {

    /** How many parent sheets up a rate is looked for. */
    public static final int MAX_LEVEL = 3;

    /** A rate set on the sheet itself. */
    public Rate(String sheetId, String grade, BigDecimal pct, LocalDate from, LocalDate to) {
        this(sheetId, grade, pct, from, to, 0, 1, null, null);
    }

    /** A rate set on the sheet itself, at its version. */
    public Rate(String sheetId, String grade, BigDecimal pct, LocalDate from, LocalDate to, int level) {
        this(sheetId, grade, pct, from, to, level, 1, null, null);
    }

    /** The same rate at a version. */
    public Rate withVersion(int version) {
        return new Rate(sheetId, grade, pct, from, to, level, version, addedAfter, replaced);
    }

    /** The same rate, forward-only past a claim id (null: for every claim), replacing an older version. */
    public Rate withHistory(Long addedAfter, Rate replaced) {
        return new Rate(sheetId, grade, pct, from, to, level, version, addedAfter, replaced);
    }

    /** The same rate seen from a sheet {@code levels} below the one it is set on. */
    public Rate up(int levels) {
        return new Rate(sheetId, grade, pct, from, to, level + levels, version, addedAfter,
                replaced == null ? null : replaced.up(levels));
    }

    /**
     * The version of this rate that applies to a claim: this one unless it is forward-only and the
     * claim was on the sheet when it was saved, then the one it replaced, and so on; null when none
     * does. A claim with no id yet (being added) sees this one.
     */
    public Rate forClaim(Long claimId) {
        if (addedAfter == null || claimId == null || claimId > addedAfter) return this;
        return replaced == null ? null : replaced.forClaim(claimId);
    }

    /**
     * The grade's rate in force on the date for a claim: as {@link #inForce(List, String, LocalDate)},
     * from the versions of the rates that apply to the claim ({@link #forClaim}).
     */
    public static Optional<BigDecimal> inForce(List<Rate> rates, String grade, LocalDate date, Long claimId) {
        return inForce(rates.stream().map((r) -> r.forClaim(claimId)).filter(Objects::nonNull).toList(), grade, date);
    }

    /**
     * The grade's rate in force on the date: on the sheet itself, else on its parent, and so on up
     * the levels (past the parents, those of the sheet it was cloned from). Empty when no level has
     * one in force.
     */
    public static Optional<BigDecimal> inForce(List<Rate> rates, String grade, LocalDate date) {
        int top = rates.stream().mapToInt(Rate::level).max().orElse(0);
        for (int level = 0; level <= top; level++) {
            Optional<BigDecimal> found = inForce(rates, grade, date, level);
            if (found.isPresent()) return found;
        }
        return Optional.empty();
    }

    /**
     * The grade's rate in force on the date at one level: the one whose from-date is the latest on
     * or before it, unless its to-date is before the date. Empty when the date is before every rate
     * the grade has there, or after the to-date of the rate that would apply.
     */
    private static Optional<BigDecimal> inForce(List<Rate> rates, String grade, LocalDate date, int level) {
        return rates.stream()
                .filter((r) -> r.level() == level)
                .filter((r) -> r.grade().equals(grade))
                .filter((r) -> r.from() == null || !r.from().isAfter(date))
                .max(Comparator.comparing(Rate::from, Comparator.nullsFirst(Comparator.naturalOrder())))
                .filter((r) -> r.to() == null || !r.to().isBefore(date))
                .map(Rate::pct);
    }
}
package net.officefloor.hq.app.rate;

import java.time.LocalDate;
import java.util.ArrayList;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.jdbc.core.RowMapper;
import org.springframework.stereotype.Repository;

/**
 * The rates store: per grade and from-date, the newest version of its rate (the one in force) and the
 * older versions it replaced, kept per sheet.
 */
@Repository
public class RateRepository {

    private static final RowMapper<Rate> ROW = (rs, n) -> new Rate(rs.getString("sheet_id"),
            rs.getString("grade"), rs.getBigDecimal("pct"), rs.getObject("from_date", LocalDate.class),
            rs.getObject("to_date", LocalDate.class), 0, rs.getInt("version"),
            rs.getObject("added_after", Long.class), null);

    private final JdbcTemplate jdbc;

    public RateRepository(JdbcTemplate jdbc) {
        this.jdbc = jdbc;
    }

    /**
     * The sheet's rates, by grade then from-date (none first), then those of its parent sheet and on
     * up to {@link Rate#MAX_LEVEL} levels, then those of the sheet it was cloned from and on up its
     * own (see {@link #ancestors}), each at its level.
     */
    public List<Rate> findAll(String sheetId) {
        List<Rate> all = new ArrayList<>(findOwn(sheetId));
        List<String> ancestors = ancestors(sheetId);
        for (int i = 0; i < ancestors.size(); i++) {
            int level = i + 1;
            findOwn(ancestors.get(i)).forEach((r) -> all.add(r.up(level)));
        }
        return all;
    }

    /**
     * The sheets a rate is looked for on after the sheet itself, in order: its parent, its parent's
     * parent and so on, up to {@link Rate#MAX_LEVEL} of them; then, when it was cloned, the sheet it
     * was cloned from and that sheet's own (its parents, then the sheet it was cloned from, and so on).
     */
    private List<String> ancestors(String sheetId) {
        List<String> ancestors = new ArrayList<>();
        java.util.Set<String> seen = new java.util.HashSet<>(List.of(sheetId));
        String sheet = sheetId;
        while (sheet != null) {
            String at = sheet;
            for (int up = 0; up < Rate.MAX_LEVEL; up++) {
                at = column("parent_id", at);
                if (at == null || !seen.add(at)) break;
                ancestors.add(at);
            }
            sheet = column("cloned_from", sheet);
            if (sheet == null || !seen.add(sheet)) break;
            ancestors.add(sheet);
        }
        return ancestors;
    }

    private String column(String column, String sheetId) {
        List<String> found = jdbc.query("SELECT " + column + " FROM sheet WHERE id = ?",
                (rs, n) -> rs.getString(column), sheetId);
        return found.isEmpty() ? null : found.get(0);
    }

    /**
     * The rates set on the sheet itself, by grade then from-date (none first), each with the older
     * versions it replaced (for the claims a forward-only version does not apply to).
     */
    private List<Rate> findOwn(String sheetId) {
        Map<String, Rate> older = new LinkedHashMap<>();
        jdbc.query("SELECT sheet_id, grade, pct, from_date, to_date, version, added_after FROM rate_version"
                + " WHERE sheet_id = ? ORDER BY version, id", (rs) -> {
                    Rate rate = ROW.mapRow(rs, 0);
                    String key = key(rate);
                    older.put(key, rate.withHistory(rate.addedAfter(), older.get(key)));
                }, sheetId);
        return jdbc.query("SELECT sheet_id, grade, pct, from_date, to_date, version, added_after FROM rate"
                + " WHERE sheet_id = ? ORDER BY grade, from_date NULLS FIRST", ROW, sheetId).stream()
                .map((r) -> r.withHistory(r.addedAfter(), older.get(key(r))))
                .toList();
    }

    private static String key(Rate rate) {
        return rate.grade() + "|" + rate.from();
    }

    /**
     * Set the grade's rate from its from-date as a new version: any it had for that from-date is kept
     * as an older version. A rate with a from-date on or after the sheet's today is forward-only: it
     * applies only to claims added after now (those above the highest claim id). Returns the rate at
     * its version.
     */
    public Rate save(Rate rate) {
        String where = " WHERE sheet_id = ? AND grade = ? AND from_date IS NOT DISTINCT FROM ?";
        jdbc.update("INSERT INTO rate_version (sheet_id, grade, from_date, version, pct, to_date, added_after)"
                + " SELECT sheet_id, grade, from_date, version, pct, to_date, added_after FROM rate" + where,
                rate.sheetId(), rate.grade(), rate.from());
        Integer last = jdbc.queryForObject("SELECT MAX(version) FROM rate" + where, Integer.class,
                rate.sheetId(), rate.grade(), rate.from());
        LocalDate today = jdbc.queryForObject("SELECT today FROM sheet WHERE id = ?", LocalDate.class, rate.sheetId());
        Long addedAfter = rate.from() != null && today != null && !rate.from().isBefore(today)
                ? jdbc.queryForObject("SELECT COALESCE(MAX(id), 0) FROM claim", Long.class)
                : null;
        Rate saved = rate.withVersion(last == null ? 1 : last + 1).withHistory(addedAfter, null);
        jdbc.update("DELETE FROM rate" + where, rate.sheetId(), rate.grade(), rate.from());
        jdbc.update("INSERT INTO rate (sheet_id, grade, pct, from_date, to_date, version, added_after)"
                + " VALUES (?, ?, ?, ?, ?, ?, ?)",
                saved.sheetId(), saved.grade(), saved.pct(), saved.from(), saved.to(), saved.version(), addedAfter);
        jdbc.update("INSERT INTO rate_history (sheet_id, grade, pct, from_date, to_date, set_on, added_after)"
                + " VALUES (?, ?, ?, ?, ?, ?, ?)",
                rate.sheetId(), rate.grade(), rate.pct(), rate.from(), rate.to(), today, addedAfter);
        return saved;
    }

    /**
     * The sheet's rates as they stood at the end of {@code day}: for each grade and from-date, the
     * last rate set for them while the sheet's today was on or before it, its version counting those
     * set for them by then; then its parent sheets' (as they are named now), each at its level and read
     * the same way: those set while the parent's own today was on or before {@code day}.
     */
    public List<Rate> findAsOf(String sheetId, LocalDate day) {
        List<Rate> all = new ArrayList<>(findOwnAsOf(sheetId, day));
        List<String> ancestors = ancestors(sheetId);
        for (int i = 0; i < ancestors.size(); i++) {
            int level = i + 1;
            findOwnAsOf(ancestors.get(i), day).forEach((r) -> all.add(r.up(level)));
        }
        return all;
    }

    private List<Rate> findOwnAsOf(String sheetId, LocalDate day) {
        Map<String, Rate> latest = new LinkedHashMap<>();
        jdbc.query("SELECT sheet_id, grade, pct, from_date, to_date, 1 AS version, added_after FROM rate_history"
                + " WHERE sheet_id = ? AND set_on <= ? ORDER BY id", (rs) -> {
                    Rate rate = ROW.mapRow(rs, 0);
                    String key = key(rate);
                    Rate before = latest.get(key);
                    latest.put(key, before == null ? rate
                            : rate.withVersion(before.version() + 1).withHistory(rate.addedAfter(), before));
                }, sheetId, java.sql.Date.valueOf(day));
        return new ArrayList<>(latest.values());
    }
}
